   "destPort": "Any",
   "destCidr": "Any",
   "syslogEnabled": false
  }
 ],
 "syslogDefaultRule": false
}
FWSHIFT_EOF
if [ "${DRY_RUN:-0}" = 1 ]; then echo "DRY_RUN: the bodies are in $OUT"; exit 0; fi
: "${MERAKI_API_KEY:?set MERAKI_API_KEY}"
: "${NETWORK_ID:?set NETWORK_ID}"
MERAKI_BASE="${MERAKI_BASE:-https://api.meraki.com/api/v1}"
api GET "/networks/$NETWORK_ID/appliance/firewall/l3FirewallRules" > "$OUT/before-l3FirewallRules.json"
api PUT "/networks/$NETWORK_ID/appliance/firewall/l3FirewallRules" "$OUT/l3FirewallRules.json" > "$OUT/after-l3FirewallRules.json"
sleep 0.2
echo "done; the tables as they were are in $OUT/before-*.json"
# Not written:
#   Never to the blocklist (floating) 2: references 'Geo_block': an alias of type 'geoip' (the countries of a GeoIP database), whose addresses are not in the configuration
#   Guests never to the blocklist: not converted: it matches the source of traffic that leaves, which is the source after outbound NAT
#   Voice from the partner - pass: the source of the rule is in zone WAN, and the MX names no zone: give the networks behind WAN with --zone-network
#   VPN users to the web servers: the source of the rule is in zone OpenVPN, VPNSITE, and the MX names no zone: give the networks behind OpenVPN, VPNSITE with --zone-network
#   Inside may ping (old kind): the source of the rule is in zone LAN, DMZ, and the MX names no zone: give the networks behind LAN, DMZ with --zone-network; an ICMP type, or a protocol other than TCP, UDP, ICMP and ICMPv6: the MX has no field for it
#   Default allow LAN to any rule: the source of the rule is in zone LAN, and the MX names no zone: give the networks behind LAN with --zone-network
#   Web publishing: the source of the rule is in zone WAN, and the MX names no zone: give the networks behind WAN with --zone-network
#   DMZ ICMPv6: the source of the rule is in zone DMZ, and the MX names no zone: give the networks behind DMZ with --zone-network; an ICMP type, or a protocol other than TCP, UDP, ICMP and ICMPv6: the MX has no field for it
#   Servers fetch updates: the source of the rule is in zone DMZ, and the MX names no zone: give the networks behind DMZ with --zone-network; 'Updates' holds members only its platform knows
#   Servers fetch updates 2: the source of the rule is in zone DMZ, and the MX names no zone: give the networks behind DMZ with --zone-network
#   Servers fetch updates 3: the source of the rule is in zone DMZ, and the MX names no zone: give the networks behind DMZ with --zone-network; 'Updates' holds members only its platform knows
#   Servers fetch updates 4: the source of the rule is in zone DMZ, and the MX names no zone: give the networks behind DMZ with --zone-network
#   Guests to the portal (no protocol, both IP versions): the source of the rule is in zone GUEST, and the MX names no zone: give the networks behind GUEST with --zone-network
#   Guests interactive (tos): not converted: it matches the type of service (tos) '0x10'; the source of the rule is in zone GUEST, and the MX names no zone: give the networks behind GUEST with --zone-network
#   VPN users to LAN web (old kind): the source of the rule is in zone OpenVPN, VPNSITE, and the MX names no zone: give the networks behind OpenVPN, VPNSITE with --zone-network
#   SSH to bastion (rule the port forward registers): the source of the rule is in zone WAN, and the MX names no zone: give the networks behind WAN with --zone-network
#   Time for everyone (floating, not quick): the source of the rule is in zone WAN, LAN, DMZ, GUEST, and the MX names no zone: give the networks behind WAN, LAN, DMZ, GUEST with --zone-network
